def check_parking_counts(timeout: int = 120) -> str:
    """Run ARR parking count scenario checks."""
    import os, subprocess
    backend = os.getenv('ARR_BACKEND_DIR', r'D:\Data\25_ACE\ARR\backend')
    candidates = [os.getenv('ARR_PYTHON', ''), os.path.join(backend, '.venv', 'Scripts', 'python.exe'), '/mnt/d/Data/25_ACE/ARR/backend/.venv/bin/python', 'python']
    python = next((p for p in candidates if p and (p == 'python' or os.path.exists(p))), 'python')
    cmd = [python, 'law/scripts/check_parking_counts.py', '--uri', os.getenv('NEO4J_URI', 'bolt://172.27.80.1:7687'), '--user', os.getenv('NEO4J_USER', 'neo4j'), '--password', os.getenv('NEO4J_PASSWORD', '')]
    try:
        result = subprocess.run(cmd, cwd=backend, text=True, capture_output=True, timeout=timeout)
        return result.stdout + ('\nSTDERR:\n' + result.stderr if result.stderr else '')
    except Exception as e:
        return f'ERROR: {e}'

